import{_ as c,a as d,b as u,c as g,d as m}from"./chunks/page_023.9U8qtNzb.js";import{_ as h,C as e,o as a,c as t,a2 as s,j as i,E as o,w as n,a as f}from"./chunks/framework.DkXPQl_e.js";const q=JSON.parse('{"title":"Lec.4 集成电路设计流程","description":"","frontmatter":{},"headers":[],"relativePath":"lectures/lec4.md","filePath":"lectures/lec4.md","lastUpdated":null}'),b={name:"lectures/lec4.md"},T={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.339ex"},xmlns:"http://www.w3.org/2000/svg",width:"4.156ex",height:"1.885ex",role:"img",focusable:"false",viewBox:"0 -683 1837 833","aria-hidden":"true"};function Q(w,l,x,k,D,y){const r=e("mjx-assistive-mml"),p=e("mjx-container");return a(),t("div",null,[l[7]||(l[7]=s('<h1 id="lec-4-集成电路设计流程" tabindex="-1">Lec.4 集成电路设计流程 <a class="header-anchor" href="#lec-4-集成电路设计流程" aria-label="Permalink to &quot;Lec.4 集成电路设计流程&quot;">​</a></h1><blockquote><p><strong><em>Design Process</em></strong></p></blockquote><p>IC 是复杂系统。设计流程的意义不是“形式主义”，而是避免团队在复杂问题中靠直觉乱试，尤其避免在错误方向上投入太多时间。Integrated circuit design 必须用清晰的 process 把 specification、conceptual design、block implementation、simulation、layout、testing 串起来。</p><h2 id="为什么-ic-设计需要-process" tabindex="-1">为什么 IC 设计需要 process？ <a class="header-anchor" href="#为什么-ic-设计需要-process" aria-label="Permalink to &quot;为什么 IC 设计需要 process？&quot;">​</a></h2><p>IC 设计常见问题有：</p><ul><li>系统太复杂，单靠局部直觉容易漏掉 constraint；</li><li>requirement 不完整或不够具体；</li><li>同一功能存在多个 architecture；</li><li>cost、area、power、speed、noise 等目标互相冲突；</li><li>早期 warning signs 容易被忽略；</li><li>fabricated chip 出错后修改代价非常高。</li></ul><p>所以一个设计流程要做三件事：</p><ol><li>让团队知道当前阶段应该完成什么；</li><li>用客观 criteria 判断是否进入下一阶段；</li><li>尽早 kill bad design，避免后期返工。</li></ol><h2 id="stage-gate-思想" tabindex="-1">Stage-Gate 思想 <a class="header-anchor" href="#stage-gate-思想" aria-label="Permalink to &quot;Stage-Gate 思想&quot;">​</a></h2><p>Stage-Gate process 的核心不是某张固定流程图，而是这个原则：</p><ul><li>follow the process；</li><li>do not skip steps；</li><li>每个 gate 都要有 clear pass criteria；</li><li><strong>kill early, kill quick</strong>。</li></ul><p>在 IC 里，这个思想非常重要。因为越往后，错误越贵：</p><ul><li>specification 阶段发现问题：改文档；</li><li>schematic 阶段发现问题：改电路；</li><li>layout 阶段发现问题：改版图；</li><li>tape-out 后发现问题：改 mask / respin，成本巨大。</li></ul><h2 id="general-design-flow" tabindex="-1">General Design Flow <a class="header-anchor" href="#general-design-flow" aria-label="Permalink to &quot;General Design Flow&quot;">​</a></h2><p>课件给出的通用流程可以整理为：</p><p><img src="'+c+'" alt="General design flow"></p><blockquote><p>图示保留原因：这里是 Part 1 后续所有设计方法的骨架。</p></blockquote><ol><li><strong>Specifications</strong><ul><li>明确系统要做什么；</li><li>给出 voltage、gain、bandwidth、power、area、temperature、interface 等指标。</li></ul></li><li><strong>Conceptual Design</strong><ul><li>把 specification 转成 block diagram；</li><li>决定 analog/digital/mixed-signal partition。</li></ul></li><li><strong>Block Implementation</strong><ul><li>为每个 block 选择 topology；</li><li>做 hand calculation 和初步 sizing。</li></ul></li><li><strong>Simulation</strong><ul><li>验证每个 block；</li><li>如果不满足要求，反馈到 design。</li></ul></li><li><strong>Prototyping / Fabrication</strong><ul><li>在课程中多是工具级或项目级 prototype；</li><li>工业中对应 silicon implementation。</li></ul></li><li><strong>Testing</strong><ul><li>对真实或后仿结果做 measurement；</li><li>判断是否满足 datasheet specification。</li></ul></li></ol><h2 id="specification-到-conceptual-design" tabindex="-1">Specification 到 Conceptual Design <a class="header-anchor" href="#specification-到-conceptual-design" aria-label="Permalink to &quot;Specification 到 Conceptual Design&quot;">​</a></h2><p>Specification 是设计的入口，但通常不是直接可实现的电路图。把 specs 转成 conceptual design 是最难的一步之一。</p><p>难点包括：</p><ul><li>requirements may not be specific enough；</li><li>more than one solution is possible；</li><li>需要理解系统工作方式；</li><li>constraints may conflict，例如 cost、space、power；</li><li>经验会帮助减少无效搜索。</li></ul><p>例如“设计一个 amplifier”不能只说“gain 高”。必须明确：</p><ul><li>gain = ? dB；</li><li>bandwidth = ?；</li><li>supply voltage range = ?；</li><li>ripple / noise / distortion limit = ?；</li><li>load 是什么；</li><li>process / area / power 限制是什么。</li></ul><h2 id="simplified-vs-detailed-design-flow" tabindex="-1">Simplified vs Detailed Design Flow <a class="header-anchor" href="#simplified-vs-detailed-design-flow" aria-label="Permalink to &quot;Simplified vs Detailed Design Flow&quot;">​</a></h2><p>简化流程通常是：</p><p><img src="'+d+'" alt="Simplified design flow"></p><p>Design concept → initial design → simulation → redesign，直到 design correct。</p><p>更完整的产品流程还包括 prototype、testing、minor correction、final product：</p><p><img src="'+u+'" alt="Detailed design flow"></p><p>区别在于：</p><ul><li>simplified flow 适合解释 iteration；</li><li>detailed flow 更接近工程项目，会区分 simulation pass 和 prototype/test pass。</li></ul><h2 id="documentation-与-datasheet" tabindex="-1">Documentation 与 Datasheet <a class="header-anchor" href="#documentation-与-datasheet" aria-label="Permalink to &quot;Documentation 与 Datasheet&quot;">​</a></h2><p>Documentation 不是最后才写的报告，而是贯穿设计流程的工程记录。</p><p>Data sheet / specs sheet 用来描述 device 或 system 的 performance and characteristics。电子器件 datasheet 通常包含：</p><ul><li>features；</li><li>key parameters；</li><li>pin configuration；</li><li>absolute maximum ratings；</li><li>DC performance；</li><li>AC performance；</li><li>parameter graphs；</li><li>application circuits。</li></ul><p>关键点：datasheet 不只是产品完成后给客户看的。设计早期就要定义 preliminary datasheet，因为它实际上规定了 design target。</p><h2 id="datasheet-如何反过来驱动设计" tabindex="-1">Datasheet 如何反过来驱动设计？ <a class="header-anchor" href="#datasheet-如何反过来驱动设计" aria-label="Permalink to &quot;Datasheet 如何反过来驱动设计？&quot;">​</a></h2><p>假设要设计一个 amplifier：</p>',39)),i("ul",null,[l[3]||(l[3]=i("li",null,"Gain = 60 dB；",-1)),l[4]||(l[4]=i("li",null,"Bandwidth = 600 Hz to 25 kHz；",-1)),i("li",null,[o(p,{class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},{default:n(()=>[(a(),t("svg",T,[...l[0]||(l[0]=[i("g",{stroke:"currentColor",fill:"currentColor","stroke-width":"0",transform:"scale(1,-1)"},[i("g",{"data-mml-node":"math"},[i("g",{"data-mml-node":"msub"},[i("g",{"data-mml-node":"mi"},[i("path",{"data-c":"1D449",d:"M52 648Q52 670 65 683H76Q118 680 181 680Q299 680 320 683H330Q336 677 336 674T334 656Q329 641 325 637H304Q282 635 274 635Q245 630 242 620Q242 618 271 369T301 118L374 235Q447 352 520 471T595 594Q599 601 599 609Q599 633 555 637Q537 637 537 648Q537 649 539 661Q542 675 545 679T558 683Q560 683 570 683T604 682T668 681Q737 681 755 683H762Q769 676 769 672Q769 655 760 640Q757 637 743 637Q730 636 719 635T698 630T682 623T670 615T660 608T652 599T645 592L452 282Q272 -9 266 -16Q263 -18 259 -21L241 -22H234Q216 -22 216 -15Q213 -9 177 305Q139 623 138 626Q133 637 76 637H59Q52 642 52 648Z",style:{"stroke-width":"3"}})]),i("g",{"data-mml-node":"TeXAtom",transform:"translate(616,-150) scale(0.707)","data-mjx-texclass":"ORD"},[i("g",{"data-mml-node":"mi"},[i("path",{"data-c":"1D437",d:"M287 628Q287 635 230 637Q207 637 200 638T193 647Q193 655 197 667T204 682Q206 683 403 683Q570 682 590 682T630 676Q702 659 752 597T803 431Q803 275 696 151T444 3L430 1L236 0H125H72Q48 0 41 2T33 11Q33 13 36 25Q40 41 44 43T67 46Q94 46 127 49Q141 52 146 61Q149 65 218 339T287 628ZM703 469Q703 507 692 537T666 584T629 613T590 629T555 636Q553 636 541 636T512 636T479 637H436Q392 637 386 627Q384 623 313 339T242 52Q242 48 253 48T330 47Q335 47 349 47T373 46Q499 46 581 128Q617 164 640 212T683 339T703 469Z",style:{"stroke-width":"3"}})]),i("g",{"data-mml-node":"mi",transform:"translate(828,0)"},[i("path",{"data-c":"1D437",d:"M287 628Q287 635 230 637Q207 637 200 638T193 647Q193 655 197 667T204 682Q206 683 403 683Q570 682 590 682T630 676Q702 659 752 597T803 431Q803 275 696 151T444 3L430 1L236 0H125H72Q48 0 41 2T33 11Q33 13 36 25Q40 41 44 43T67 46Q94 46 127 49Q141 52 146 61Q149 65 218 339T287 628ZM703 469Q703 507 692 537T666 584T629 613T590 629T555 636Q553 636 541 636T512 636T479 637H436Q392 637 386 627Q384 623 313 339T242 52Q242 48 253 48T330 47Q335 47 349 47T373 46Q499 46 581 128Q617 164 640 212T683 339T703 469Z",style:{"stroke-width":"3"}})])])])])],-1)])])),o(r,{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},{default:n(()=>[...l[1]||(l[1]=[i("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[i("msub",null,[i("mi",null,"V"),i("mrow",{"data-mjx-texclass":"ORD"},[i("mi",null,"D"),i("mi",null,"D")])])],-1)])]),_:1})]),_:1}),l[2]||(l[2]=f(" between 7 V and 12 V；",-1))]),l[5]||(l[5]=i("li",null,"Ripple < 1 dB；",-1)),l[6]||(l[6]=i("li",null,"Max gain for amplifier stage = 40 dB。",-1))]),l[8]||(l[8]=s('<p>这些 specs 会直接决定 architecture：</p><ul><li>单级最大 40 dB，但总 gain 需要 60 dB，因此至少需要多级；</li><li>bandwidth 限制会影响 compensation 和 pole placement；</li><li>supply range 会限制 output swing 和 bias；</li><li>ripple/noise 会影响 topology 和 filtering。</li></ul><p>所以 datasheet 是 design 的输入，不只是输出。</p><h2 id="mixed-signal-design-flow" tabindex="-1">Mixed-Signal Design Flow <a class="header-anchor" href="#mixed-signal-design-flow" aria-label="Permalink to &quot;Mixed-Signal Design Flow&quot;">​</a></h2><p>Mixed-signal system 的困难在于 analog 和 digital 的设计方法不同，但最后必须在同一 chip 上合并。</p><p><img src="'+g+'" alt="Mixed-signal design flow"></p><p>一个典型流程可以理解为：</p><ul><li>Analog side: <ul><li>schematic capture；</li><li>analog simulation；</li><li>block layout；</li><li>physical verification；</li><li>post-layout simulation。</li></ul></li><li>Digital side: <ul><li>design entry；</li><li>behavioral simulation；</li><li>synthesis；</li><li>place and route；</li><li>functional verification。</li></ul></li><li>Mixed-signal integration: <ul><li>mixed-signal analysis；</li><li>chip assembly；</li><li>analog verification manager / functional verification。</li></ul></li></ul><p>关键问题是 interface：analog continuous signal 和 digital discrete state 必须通过 ADC、DAC、clock、comparator、level shifter 等边界模块连接。</p><h2 id="analog-design-flow" tabindex="-1">Analog Design Flow <a class="header-anchor" href="#analog-design-flow" aria-label="Permalink to &quot;Analog Design Flow&quot;">​</a></h2><p>Analog design 的流程通常更依赖 hand calculation、simulation、layout parasitics 和测试反馈。</p><p><img src="'+m+'" alt="Analog design flow"></p><p>典型步骤：</p><ol><li>define circuit I/O specs；</li><li>hand calculations and schematics；</li><li>circuit simulation；</li><li>layout；</li><li>re-simulate with parasitics；</li><li>prototype fabrication；</li><li>test and evaluate；</li><li>判断是 specification problem 还是 fabrication problem。</li></ol><p>Analog 电路尤其怕 parasitics。schematic pass 不代表 layout 后还能 pass。</p><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>Testing 虽然常在流程后段出现，但测试计划应当提前考虑。</p><p>Testing 的目的：</p><ul><li>validate design / IC；</li><li>通过 measurement 判断是否满足 specification；</li><li>用 statistical methods 评估 process variation；</li><li>为 datasheet 提供真实数据。</li></ul><p>Testing process 通常包括：</p><ol><li>determine test objective；</li><li>select measurement technique and test procedure；</li><li>plan how to analyse / present / use data；</li><li>take measurement；</li><li>compare against specs。</li></ol><h2 id="critical-design-review" tabindex="-1">Critical Design Review <a class="header-anchor" href="#critical-design-review" aria-label="Permalink to &quot;Critical Design Review&quot;">​</a></h2><p>IC 设计中必须主动寻找可能失败的地方：</p><ul><li>某些 digital input combination 造成 hazard；</li><li>user misuse 造成 product failure；</li><li>analog corner case 造成 performance violation；</li><li>layout parasitic 造成 oscillation / delay；</li><li>process variation 造成 yield 问题。</li></ul><p>越早识别风险，越能降低 time-to-market、extra cost 和 PR disaster。</p><h2 id="design-reuse" tabindex="-1">Design Reuse <a class="header-anchor" href="#design-reuse" aria-label="Permalink to &quot;Design Reuse&quot;">​</a></h2><p>Design reuse 指复用已经设计、仿真、验证过的 block，例如 standard cell、op-amp topology、bias circuit、ADC sub-block。</p><p>好处：</p><ul><li>reduce design cost；</li><li>reduce design time；</li><li>lower verification risk。</li></ul><p>风险：</p><ul><li>reused block 的 performance 未必满足新 specs；</li><li>old block 的 assumptions 可能不同；</li><li>process、supply、temperature、load 改变后需要重新验证。</li></ul><h2 id="本讲要点" tabindex="-1">本讲要点 <a class="header-anchor" href="#本讲要点" aria-label="Permalink to &quot;本讲要点&quot;">​</a></h2><ul><li>IC design process 是为了降低复杂度和返工风险。</li><li>Specification 是设计入口，datasheet 要在早期定义。</li><li>Conceptual design 是把 specs 转成 block architecture。</li><li>Simulation pass 不等于 final pass，layout parasitics 和 testing 会改变结论。</li><li>Mixed-signal design 需要同时处理 analog flow、digital flow 和二者接口。</li><li>Design reuse 有价值，但必须重新检查 context 和 assumptions。</li></ul>',33))])}const C=h(b,[["render",Q]]);export{q as __pageData,C as default};
